<script setup>
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowRight, Wallet, Clock, Shop, Document, Refresh, CopyDocument } from '@element-plus/icons-vue'
import request from '@/utils/request'
import PurchaseFeedback from '@/components/PurchaseFeedback.vue'
const props=defineProps({mode:{type:String,default:'bill'},orderId:String})
const router=useRouter(),data=ref(null),shops=ref([]),agreed=ref(false),busy=ref(false),repayOpen=ref(false),repayTarget=ref(null),repayAmount=ref(''),clientKey=ref(''),disputeOpen=ref(false),reason=ref('')
const money=value=>(Number(value||0)/100).toFixed(2)
const date=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'
const labels={WAITING_MERCHANT:'待商家发布',PUBLISHED:'待顾客确认',CONFIRMED:'已确认 · 待核销',FULFILLED:'已核销',CANCELLED:'已取消',EXPIRED:'已过期',OPEN:'待还',PARTIAL:'部分已结清',SETTLED:'已结清',PENDING:'等待模拟结果',FAILED:'演示失败',CLOSED:'已关闭',EXCEPTION:'差异待复核'}
const order=computed(()=>data.value?.orders.find(o=>o.id===props.orderId))
const account=computed(()=>data.value?.account)
const waiting=computed(()=>data.value?.requests.filter(r=>r.status==='WAITING_MERCHANT')||[])
const pendingOrders=computed(()=>data.value?.orders.filter(o=>['PUBLISHED','CONFIRMED'].includes(o.status))||[])
const activeBills=computed(()=>data.value?.receivables.filter(r=>r.outstandingMinor>0)||[])
const orderBill=computed(()=>data.value?.receivables.find(r=>r.orderId===order.value?.id))
const reservation=computed(()=>data.value?.reservations.find(r=>r.orderId===order.value?.id))
const events=computed(()=>data.value?.events.filter(e=>e.orderId===order.value?.id)||[])
const storeName=merchantUid=>shops.value.find(s=>'s'+String(s.id).padStart(7,'0')===merchantUid)?.nickname||merchantUid
const findOrder=id=>data.value?.orders.find(o=>o.id===id)
const goOrder=id=>router.push({path:'/mall/deferredOrder',query:{id}})
async function load(){const [r,s]=await Promise.all([request.get('/credit/overview'),request.get('/unit')]);if(r.code==='200')data.value=r.data;else ElMessage.error(r.msg);shops.value=s.data||[]}
async function action(name,payload,success){if(busy.value)return null;busy.value=true;try{const r=await request.post('/credit/'+name,payload);if(r.code!=='200'){ElMessage.error(r.msg);return null}if(success)ElMessage.success(success);await load();return r.data}finally{busy.value=false}}
async function confirm(){const o=order.value;if(!agreed.value)return ElMessage.info('请先核对并勾选演示交易说明');await action('confirm',{orderId:o.id,credential:o.confirmationCredential?.credential,version:o.version,snapshotHash:o.snapshotHash,agreementAccepted:agreed.value},'顾客已确认，额度已预占；尚未生成应收')}
async function code(){await action('fulfillment-code',{orderId:order.value.id},'演示核销码已生成，旧码会作废')}
async function copyCode(){try{await navigator.clipboard.writeText(order.value.fulfillmentCredential.credential);ElMessage.success('核销码已复制')}catch{ElMessage.info('请长按或手动复制演示核销码')}}
function openRepay(receivable){repayTarget.value=receivable;repayAmount.value=money(receivable.outstandingMinor);clientKey.value='UI-'+Date.now()+'-'+Math.random().toString(16).slice(2);repayOpen.value=true}
async function repay(){const amount=Math.round(Number(repayAmount.value)*100),r=repayTarget.value;if(!Number.isSafeInteger(amount)||amount<=0||amount>r.outstandingMinor)return ElMessage.warning('请输入不超过当前待还本金的金额');const result=await action('repay',{merchantUid:r.merchantUid,receivableIds:[r.id],amountMinor:amount,clientKey:clientKey.value},'演示还款已提交，等待平台模拟渠道结果；额度尚未变化');if(result)repayOpen.value=false}
function openDispute(receivable){repayTarget.value=receivable;reason.value='';disputeOpen.value=true}
async function dispute(){const result=await action('dispute',{receivableId:repayTarget.value.id,reason:reason.value},'示例异议已提交，处理完成前暂停新增确认');if(result)disputeOpen.value=false}
let timer
const sync=event=>{if(event.key==='mall-ui-data-v2')load()}
onMounted(()=>{load();timer=setInterval(load,30000);window.addEventListener('storage',sync)})
onUnmounted(()=>{clearInterval(timer);window.removeEventListener('storage',sync)})
watch(()=>props.orderId,()=>{agreed.value=false;load()})
</script>
<template>
<div v-if="data" class="credit-customer">
<template v-if="mode==='bill'">
  <section class="credit-wallet"><div class="wallet-label">先吃后付 <span>SIMULATION</span></div><p>可用额度</p><h2>¥{{money(account?.availableMinor)}}</h2><div class="wallet-grid"><div><small>总额度</small><strong>¥{{money(account?.totalMinor)}}</strong></div><div><small>待核销预占</small><strong>¥{{money(account?.reservedMinor)}}</strong></div><div><small>待还本金</small><strong>¥{{money(account?.principalMinor)}}</strong></div></div><p v-if="account?.blocked" class="wallet-block">{{account.overdue?'存在逾期示例账单':account.disputed?'存在待处理异议':'账户已冻结'}}，暂不可新增确认；仍可查询和还款</p></section>
  <section class="native-card credit-guide"><strong>怎么用先吃后付？</strong><p>提交用餐请求 → 商家发布 → 你确认额度预占 → 商家核销生账单 → 演示还款</p><button @click="router.push('/mall/category')">去选餐 <ArrowRight/></button></section>
  <section v-if="waiting.length" class="native-card"><h3 class="accent-title">待商家发布</h3><article v-for="r in waiting" :key="r.id" class="credit-row"><div class="credit-row-title"><strong>{{r.items.map(i=>i.name).join('、')}}</strong><b>¥{{money(r.totalMinor)}}</b></div><p>{{storeName(r.merchantUid)}} · {{r.id}}</p><small>此时未占额度、未生应收</small><button class="credit-text-button" @click="action('cancel-request',{requestId:r.id},'请求已取消')">取消请求</button></article></section>
  <section v-if="pendingOrders.length" class="native-card"><h3 class="accent-title">待处理订单</h3><article v-for="o in pendingOrders" :key="o.id" class="credit-row" @click="goOrder(o.id)"><div class="credit-row-title"><strong>{{o.items.map(i=>i.name).join('、')}}</strong><b>¥{{money(o.totalMinor)}}</b></div><p>{{storeName(o.merchantUid)}} · {{o.id}}</p><div class="credit-row-title"><span :class="['credit-status',o.status]">{{labels[o.status]}}</span><button class="primary-pill">{{o.status==='PUBLISHED'?'核对并确认':'出示核销码'}}</button></div></article></section>
  <section class="native-card"><div class="credit-section-heading"><h3 class="accent-title">我的账单</h3><button @click="load"><Refresh/>刷新</button></div><article v-for="r in activeBills" :key="r.id" class="credit-row"><div class="credit-row-title"><strong>{{storeName(r.merchantUid)}}</strong><b class="red">¥{{money(r.outstandingMinor)}}</b></div><p>{{findOrder(r.orderId)?.items.map(i=>i.name).join('、')}}</p><p>{{r.id}} · {{labels[r.status]}}</p><p :class="{red:r.overdue}">应还时间：{{date(r.dueAt)}} {{r.overdue?'（演示逾期）':''}}</p><div class="credit-row-actions"><button @click="goOrder(r.orderId)">查看订单</button><button @click="router.push({path:'/mall/orderService',query:{creditId:r.orderId}})">评价与售后</button><button @click="openDispute(r)">账单异议</button><button class="primary-pill" @click="openRepay(r)">演示还款</button></div></article><div v-if="!activeBills.length" class="native-empty">暂无待还本金<br><small>额度预占不等于已产生应收</small></div></section>
  <section v-if="data.repayments.length" class="native-card"><h3 class="accent-title">还款记录</h3><article v-for="p in [...data.repayments].reverse()" :key="p.id" class="credit-row"><div class="credit-row-title"><strong>{{p.status==='CONFIRMED'?'演示还款已确认':labels[p.status]}}</strong><b>¥{{money(p.amountMinor)}}</b></div><p>{{p.id}} · {{storeName(p.merchantUid)}}</p><p>实际释放本金 ¥{{money(p.allocations.reduce((s,a)=>s+a.amountMinor,0))}}</p><p v-if="p.status==='PENDING'">{{p.channelResult==='UNKNOWN'?'渠道结果未知，仍在处理中':'等待平台模拟结果控制员确认'}}，此时不释放额度</p><p v-if="p.unallocatedMinor">待分配 / 应退余额 ¥{{money(p.unallocatedMinor)}}，不额外增加额度</p><p>{{date(p.createdAt)}}</p></article></section>
  <section v-if="data.receivables.some(r=>r.status==='SETTLED')" class="native-card"><h3 class="accent-title">已结清</h3><div v-for="r in data.receivables.filter(r=>r.status==='SETTLED')" :key="r.id" class="native-line" role="button" tabindex="0" @click="goOrder(r.orderId)" @keydown.enter="goOrder(r.orderId)"><span>{{r.orderId}}</span><b>¥{{money(r.issuedMinor)}} 已结清</b></div></section>
  <section class="native-card native-line" @click="router.push('/mall/afterSales')"><strong>售后 / 退款进度</strong><ArrowRight/></section><section v-if="data.disputes.length" class="native-card"><h3 class="accent-title">账单异议进度</h3><article v-for="d in data.disputes" :key="d.id" class="credit-row"><strong>{{d.id}} · {{d.status==='RESOLVED'?'已处理':'待处理'}}</strong><p>{{d.reason}}</p><p v-if="d.resolution">处理结果：{{d.resolution}}</p></article></section><p class="checkout-disclaimer">原代码演示夹具：总额度¥{{money(data.rule.quotaMinor)}}、单笔¥{{money(data.rule.transactionMaxMinor)}}、履约后{{data.rule.termDays}}天应还。非正式授信规则，不产生真实债务、扣款、利息或手续费。保证金和平台结算不适用。</p>
</template>
<template v-else-if="order">
  <section class="credit-order-heading"><span>{{labels[order.status]}}</span><h2>¥{{money(order.totalMinor)}}</h2><p>{{order.id}}</p><p v-if="order.status==='PUBLISHED'">确认截止 {{date(order.expiresAt)}}</p><p v-if="order.status==='CONFIRMED'">预占截止 {{date(reservation?.expiresAt)}}</p></section>
  <section class="native-card"><h3>{{storeName(order.merchantUid)}}</h3><article v-for="item in order.items" :key="item.productId" class="native-product-row compact"><img :src="item.img" :alt="item.name"/><div><h4>{{item.name}}</h4><p>¥{{money(item.unitPriceMinor)}} × {{item.quantity}}</p><strong>¥{{money(item.subtotalMinor)}}</strong></div></article><div class="native-line"><span>订单备注</span><span>{{order.remark||'无'}}</span></div><div class="native-line"><span>订单规则快照</span><span>{{order.ruleCode}}</span></div><div class="native-line"><span>核销后应还期限</span><strong>{{order.ruleSnapshot.termDays}}天</strong></div></section>
  <section v-if="order.status==='PUBLISHED'" class="native-card"><h3 class="accent-title">确认先吃后付</h3><p>确认后预占 ¥{{money(order.totalMinor)}}，核销前不会生成应收。商家核销后按本订单规则生成账单。尚未核销时取消或到期会释放预占。</p><label class="credit-consent"><input type="checkbox" v-model="agreed"/><span>我已核对商家、餐品、金额和{{order.ruleSnapshot.termDays}}天演示期限，了解这不会产生真实债务或扣款</span></label><button class="primary-pill full" :disabled="busy||!agreed" @click="confirm">确认并预占 ¥{{money(order.totalMinor)}}</button><button class="credit-text-button full" @click="action('cancel',{orderId:order.id},'订单已取消')">拒绝并取消</button></section>
  <section v-if="order.status==='CONFIRMED'" class="native-card"><h3 class="accent-title">到店核销</h3><p>额度已预占 ¥{{money(order.totalMinor)}}，当前应收本金尚未增加。请生成演示核销码交给本店商家。</p><div v-if="order.fulfillmentCredential&&!order.fulfillmentCredential.revoked" class="fulfillment-ticket"><small>演示核销凭证</small><strong>{{order.fulfillmentCredential.credential}}</strong><p>有效至 {{date(order.fulfillmentCredential.expiresAt)}}</p><button @click="copyCode"><CopyDocument/> 复制核销码</button></div><button class="primary-pill full" :disabled="busy" @click="code">{{order.fulfillmentCredential?'重新生成核销码':'生成演示核销码'}}</button><p v-if="order.fulfillmentCredential" class="muted">重新生成会使旧码作废</p><button class="credit-text-button full" @click="action('cancel',{orderId:order.id},'已取消并释放预占额度')">取消订单并释放额度</button></section>
  <section v-if="order.status==='FULFILLED'&&orderBill" class="native-card"><h3 class="accent-title">履约与应收</h3><div class="native-line"><span>核销时间</span><span>{{date(order.fulfilledAt)}}</span></div><div class="native-line"><span>应收本金</span><strong>¥{{money(orderBill.issuedMinor)}}</strong></div><div class="native-line"><span>剩余本金</span><strong class="red">¥{{money(orderBill.outstandingMinor)}}</strong></div><p>应还：{{date(orderBill.dueAt)}}</p><button v-if="orderBill.outstandingMinor" class="primary-pill full" @click="openRepay(orderBill)">演示还款</button><p v-else>本笔已结清，额度按实际还款本金恢复</p><button v-if="orderBill.outstandingMinor" class="credit-text-button full" @click="openDispute(orderBill)">提出账单异议（演示）</button><p class="muted">已核销订单不能通过取消抹除应收，订单状态仍为已核销</p></section>
  <PurchaseFeedback v-if="order.status==='FULFILLED'" :credit-order-id="order.id" @updated="load" />
  <section v-if="['CANCELLED','EXPIRED'].includes(order.status)" class="native-card"><h3>{{labels[order.status]}}</h3><p>尚未履约的预占已释放，此订单没有生成应收本金</p></section>
  <section class="native-card"><h3 class="accent-title">业务动态</h3><div v-for="e in events" :key="e.id" class="credit-event"><strong>{{({ORDER_CREATED:'商家创建订单',ORDER_PUBLISHED:'商家已发布',QUOTA_HELD:'顾客确认，额度预占',RECEIVABLE_ISSUED:'商家核销，应收生成',PRINCIPAL_REPAID:'模拟结果确认，释放本金',REFUND_REQUESTED:'售后申请已提交',REFUND_APPROVED:'售后独立复核通过',REFUND_RETURNED:'模拟现金退回已完成',RESERVATION_RELEASED:'预占已释放'})[e.type]||e.type}}</strong><small>{{date(e.at)}}</small><span v-if="e.amountMinor">¥{{money(e.amountMinor)}}</span></div></section>
</template>
<div v-else class="native-empty">订单不存在或不属于当前顾客</div>
<div v-if="repayOpen" class="native-overlay" @click.self="repayOpen=false"><section class="native-sheet"><button class="sheet-close" @click="repayOpen=false">×</button><h3>演示还款</h3><p>向 {{storeName(repayTarget.merchantUid)}} 偿还本笔示例账单</p><form class="native-form" @submit.prevent="repay"><label>本次金额（元）<input v-model="repayAmount" type="number" min="0.01" step="0.01" :max="money(repayTarget.outstandingMinor)" required/></label><p>提交后为“处理中”，由平台模拟结果控制员确认后才释放实际本金。不会真实扣款。</p><button class="primary-pill full" :disabled="busy" type="submit">提交演示还款</button></form></section></div>
<div v-if="disputeOpen" class="native-overlay" @click.self="disputeOpen=false"><section class="native-sheet"><button class="sheet-close" @click="disputeOpen=false">×</button><h3>账单异议（演示）</h3><form class="native-form" @submit.prevent="dispute"><label>原因<textarea v-model="reason" placeholder="请描述需要核对的问题，不要填写敏感资料" required maxlength="500"></textarea></label><p>异议处理期间会阻止新增额度确认，历史查询和还款仍可用。</p><button class="primary-pill full" :disabled="busy" type="submit">提交示例异议</button></form></section></div>
</div>
<div v-else class="native-empty">正在读取本机业务记录…</div>
</template>
<style scoped>
.credit-wallet{margin:12px;padding:23px 20px;color:white;border-radius:12px;background:linear-gradient(125deg,#ff763a,#fb4e39)}.wallet-label{font-size:16px;font-weight:600;display:flex;justify-content:space-between;align-items:center}.wallet-label span{font-size:9px;font-weight:400;border:1px solid #ffffff80;padding:3px 6px;border-radius:4px}.credit-wallet>p{font-size:12px;opacity:.85;margin:22px 0 4px}.credit-wallet h2{font-size:37px;margin:0 0 22px}.wallet-grid{display:grid;grid-template-columns:repeat(3,1fr);padding-top:17px;border-top:1px solid #ffffff40;gap:10px}.wallet-grid small{font-size:10px;opacity:.8}.wallet-grid strong{display:block;font-size:15px;margin-top:7px}.credit-wallet .wallet-block{font-size:11px;margin:15px 0 0;padding:10px;background:#ffffff25;border-radius:5px;line-height:1.7}.credit-guide>strong{font-size:14px}.credit-guide button{color:#ff623a;font-size:12px;padding:0}.credit-guide svg{height:14px;width:14px}.credit-row{padding:16px 0;border-bottom:1px solid #f1f1f1}.credit-row:last-child{border-bottom:0}.credit-row-title{display:flex;align-items:center;justify-content:space-between;gap:10px}.credit-row-title strong{font-size:13px;font-weight:500;line-height:1.5}.credit-row-title b{font-size:16px;white-space:nowrap}.credit-row p{font-size:11px;color:#999;line-height:1.7;margin:7px 0}.credit-row>small{font-size:10px;color:#aaa}.credit-row .primary-pill{font-size:11px;padding:7px 12px}.credit-status{font-size:11px;color:#d88036}.credit-row-actions{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:12px}.credit-row-actions>button{font-size:11px}.credit-text-button{font-size:12px!important;color:#999!important;padding:7px!important}.credit-section-heading{display:flex;justify-content:space-between;align-items:flex-start}.credit-section-heading>button{font-size:11px;color:#aaa}.credit-section-heading svg{width:13px;height:13px}.credit-order-heading{padding:27px 20px;text-align:center;background:#fff0e7;color:#ca552a}.credit-order-heading>span{font-size:15px}.credit-order-heading h2{font-size:33px;margin:14px 0}.credit-order-heading p{font-size:11px;margin:8px 0;color:#aa836d}.credit-consent{display:flex;align-items:flex-start;gap:8px;font-size:12px;line-height:1.8;color:#777;margin-top:14px}.credit-consent input{margin-top:4px;flex-shrink:0}.fulfillment-ticket{padding:20px 12px;background:#fff8f0;border:1px dashed #ecc7a8;border-radius:8px;margin:18px 0;text-align:center}.fulfillment-ticket small{font-size:11px;color:#bd8a63}.fulfillment-ticket strong{display:block;font-size:19px;letter-spacing:1px;word-break:break-all;margin:14px 0;color:#222}.fulfillment-ticket p{font-size:10px;color:#aaa}.fulfillment-ticket button{font-size:12px;margin-top:12px;color:#d2773e}.fulfillment-ticket svg{width:15px;height:15px}.credit-event{padding:15px 0 15px 14px;border-left:2px solid #f1d7c5;position:relative;font-size:12px}.credit-event:before{content:'';width:6px;height:6px;border-radius:50%;background:#e9b894;position:absolute;left:-4px;top:20px}.credit-event strong{font-size:12px;font-weight:500}.credit-event small{display:block;color:#aaa;font-size:10px;margin-top:7px}.credit-event>span{display:block;font-size:12px;color:#d36b38;margin-top:7px}
</style>
